package dev.zomboid.hordes.client;
import java.util.*;import dev.zomboid.hordes.LootProfiles;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.screens.Screen;import net.minecraft.client.gui.components.Button;import net.minecraft.network.chat.Component;
public final class LootPreviewScreen extends Screen {
 private final Screen parent;private final String prefix;private final Map<String,Double> values;
 public LootPreviewScreen(Screen parent,String prefix,Map<String,Double> values){super(Component.literal("Ejemplo de loot: "+prefix));this.parent=parent;this.prefix=prefix;this.values=new HashMap<>(values);}
 protected void init(){addRenderableWidget(Button.builder(Component.literal("Volver"),b->onClose()).bounds(width/2-60,height-27,120,20).build());}
 public void onClose(){Minecraft.getInstance().setScreen(parent);}
 public void render(GuiGraphics g,int mx,int my,float delta){g.fill(0,0,width,height,0xee151718);super.render(g,mx,my,delta);int left=Math.max(14,(width-560)/2),y=12;g.drawString(font,title.getString(),left,y,0xffdcd6ca,false);y+=22;String note=values.get(prefix+"_loot_todos")>0?"Perfil personalizado. Ejemplo simulado; no garantiza un resultado concreto.":"El perfil sigue en Original. Actívalo y pulsa Aplicar para usar estos ajustes.";for(var line:font.split(Component.literal(note),width-2*left)){g.drawString(font,line,left,y,0xffacbd9e,false);y+=11;}
  double[] w=LootProfiles.weights(values,prefix);double sum=Arrays.stream(w).sum();Random random=new Random(42);int rolls=LootProfiles.rolls(10,values.get(prefix+"_cantidad"),prefix.equals("drops")?64:27,random.nextDouble());int[] counts=new int[8];for(int i=0;i<rolls;i++){int category=LootProfiles.category(w,random.nextDouble());if(category>=0)counts[category]++;}y+=10;g.drawString(font,"Base ilustrativa: 10 pilas, con espacio limitado; ejemplo: "+(sum==0?0:rolls)+" selecciones.",left,y,0xffc5c9ba,false);y+=18;for(int i=0;i<8;i++){double percentage=sum==0?0:100*w[i]/sum;String line=String.format(java.util.Locale.ROOT,"%s: %.1f%% · ejemplo %d · %s",LootProfiles.LABELS[i],percentage,counts[i],LootExamples.SAMPLE[i]);for(var wrapped:font.split(Component.literal(line),width-2*left)){if(y>=height-40)break;g.drawString(font,wrapped,left,y,0xffc5c9ba,false);y+=11;}y+=3;} }
 public boolean isPauseScreen(){return false;}
}
